"""Beginner chapters for the separately versioned Company Dash application."""
CD = 'company-dash/'

def add_guides(guide):
    guide(31, 'Company Dash startup and dashboard',
          'Run the local maintenance dashboard and understand how it connects to Nexora.',
          ['http://127.0.0.1:8000/#overview'], CD+'public/index.html', CD+'server/app.mjs', CD+'server/config.mjs',
          ['Local startup', 'Overview and navigation', 'Configuration diagnostics', 'Local request token', 'Separate repository and data'],
          ['Open the Company Dash folder in its own VS Code window and run node server/main.mjs.',
           'The Node server serves public/index.html, app.js and styles.css on loopback port 8000.',
           'The browser gets a local request token from /api/session and sends X-Command-Token with API requests.',
           'GET /api/state returns repository, tasks, runs and provider status.',
           'The browser renders the selected view; the server keeps task history in its own SQLite database.'],
          'Company Dash is a separate Node.js application, not a Nexora API module. Its public folder is the frontend; server contains the backend. It needs Node 24 or newer for built-in SQLite and has no frontend build or npm dependencies. Run it from its own folder; opening index.html as a file will not provide its API. config.example.json shows safe defaults; local configuration and data stay private. The dashboard can inspect the Nexora checkout without becoming a runtime dependency of CRM, Portal or CMS.',
          (CD+'public/index.html', 'Work board<span', 'Work requests<span', 'Change the sidebar wording only, keeping the href, data-view and span intact. Refresh Company Dash and confirm the same work view opens. Restore the text after practising.'),
          'The dashboard is local and single-user. Its request token and Host/Origin checks are not public multi-user authentication. Documentation capture does not start the dashboard, run an agent or change task history.', [2,32,33,36])
    guide(32, 'Company Dash repository and source viewer',
          'Find Nexora source and documents and understand which files enter an isolated snapshot.',
          ['http://127.0.0.1:8000/#knowledge'], CD+'public/app.js', CD+'server/repository.mjs', CD+'server/config.mjs',
          ['Repository refresh', 'File and code search', 'Source reader', 'Excluded and linked paths', 'Snapshot fingerprints'],
          ['Repository and docs renders the current inventory returned by the server.',
           'Refresh requests POST /api/repository/scan; search requests GET /api/repository/files.',
           'Selecting a file requests GET /api/repository/file with its relative path.',
           'readSource checks path confinement and rejects excluded or linked paths.',
           'An agent snapshot copies allowed current source and records fingerprints; it leaves the original checkout unchanged.'],
          'public/app.js defines knowledge() and the shared api() request helper. server/app.mjs maps the requests and delegates source access to repository.mjs. The visible inventory describes the configured Nexora repository, not the Company Dash implementation. Snapshots include allowed dirty and untracked source; secrets, runtime configuration, dependency folders and build outputs are excluded. A fingerprint is a content signature used to notice that a file or proposal changed; it is not a security review or a test result.',
          (CD+'public/app.js', 'async function searchFiles()', None, 'Read-only exercise: trace the file-search request into app.mjs, then locate readSource in repository.mjs. Explain why a path containing parent-directory traversal or a linked folder is rejected.'),
          'Snapshots are not atomic against another process editing files during capture. Refresh after source changes and review exclusions. The complete learning manual embeds a separate dated Company Dash source copy; it does not expose private local configuration or runtime databases.', [30,31,33,35])
    guide(33, 'Company Dash tasks agents and handoffs',
          'Follow a request from its form through a specialist run and a reviewed handoff.',
          ['http://127.0.0.1:8000/#work', 'http://127.0.0.1:8000/#agents'], CD+'public/app.js', CD+'server/runner.mjs', CD+'server/store.mjs',
          ['Work board and filters', 'Six specialist roles', 'Linked workflows', 'Conversations and reports', 'Queued runs cancellation and restart recovery'],
          ['The request form sends title, description, agent, area, priority and workflow choice to POST /api/tasks.',
           'The server validates the fields and stores tasks and initial messages in a SQLite transaction.',
           'A linked workflow creates dependent tasks; each waits for the previous accepted handoff.',
           'Starting a role queues a serial run in an isolated source workspace and stores logs and artifacts.',
           'The operator reviews a structured report, requests revision or accepts the handoff to unlock the next role.'],
          'The six roles are PM, BA, CRM Developer, Portal Developer, QA and Nexora Support Agent; catalog.mjs defines their names and instructions. PM, BA and Support use read-only execution, while Developer and QA write inside their isolated workspaces. Support defaults to standalone triage. Selecting a linked workflow creates a fixed sequence, not autonomous planning or automatic execution. store.mjs creates tasks, messages, runs, artifacts, events and metadata tables. A report in review is distinct from an accepted task, a passed test or applied code.',
          (CD+'public/app.js', 'function updateWorkflow()', None, 'Read-only exercise: find which roles can create a workflow and why Support starts with it unchecked. Trace Accept handoff to the server and identify the dependent-task update without clicking it.'),
          'Agent runs use the signed-in Codex provider and account limits. They may be blocked by missing dependencies or usage limits. Restarted unfinished runs are marked interrupted; inspect their logs before retrying. This chapter exercise creates no real tasks or customer messages.', [32,34,35,36])
    guide(34, 'Company Dash QA and verification',
          'Read checkout and proposal verification evidence and diagnose blocked runtime preparation.',
          ['http://127.0.0.1:8000/#qa'], CD+'public/app.js', CD+'server/runner.mjs', CD+'server/catalog.mjs',
          ['Fixed test suites', 'Checkout and proposal scope', 'Prepare test dependencies', 'Actual process logs', 'Structured reports and blocked runs'],
          ['QA and verification shows fixed suites supplied by catalog.mjs.',
           'POST /api/qa/run validates the suite and optionally a proposal task id.',
           'The runner chooses the original checkout or a separate proposal verification copy.',
           'QA-agent runtime preparation restores .NET packages and locked frontend packages before model execution.',
           'Logs, exit codes and structured status/report data identify passed, failed, cancelled or blocked work.'],
          'A checkout check evaluates the original Nexora source. Test this proposal evaluates an independent source copy associated with a task. Prepare test dependencies is a QA-agent option; setup success does not mean tests passed. If .NET assets or Playwright are missing, read the preparation log and structured blocked result. The runner must parse the model output status and report as well as the process exit code. catalog.mjs records allowed commands and timeouts rather than accepting arbitrary commands from a browser form.',
          (CD+'server/runner.mjs', 'prepareRuntime', None, 'Read-only exercise: trace prepareRuntime from enqueue to dependency setup. Find where setup failure prevents model execution, then compare a structured report with a process exit code.'),
          'The command center serializes its own checks, but other tools can still occupy test ports. Browser suites use the Nexora runner and disposable test databases; proposal fixtures do not create persistent shared CRM records. Documentation QA does not rerun these product suites.', [30,33,35])
    guide(35, 'Company Dash proposal review and integration',
          'Understand the review copy, matching source fingerprints and the explicit apply action.',
          ['Company Dash task dialog then Proposal verification'], CD+'public/app.js', CD+'server/proposals.mjs', CD+'server/repository.mjs',
          ['Cumulative proposed patches', 'Proposal test evidence', 'Accepted ancestors', 'Integration preview', 'Freshness and expiry checks', 'Explicit local apply'],
          ['Read the task report and proposed patch before starting relevant proposal QA.',
           'Review integration requests POST /api/integration/preview with a task id.',
           'The backend checks the latest proposal, accepted handoffs, exact-source QA and unchanged original baseline.',
           'A separate review copy and cumulative patch are returned for operator inspection.',
           'Apply reviewed changes revalidates the review and updates the local Nexora checkout; checkout QA follows.'],
          'public/app.js creates proposal controls and a review dialog. proposals.mjs requires passing evidence for the exact proposal fingerprint and compares the original checkout baseline. A downstream proposal includes earlier accepted developer changes. The review key expires after fifteen minutes and is revalidated on apply. Matching architecture evidence covers only that suite; choose API or browser checks when the change requires them. Applied source remains a local change until it is deliberately committed, pushed and deployed through the appropriate workflow.',
          (CD+'server/proposals.mjs', 'Run proposal QA on this exact source before integration.', None, 'Read-only exercise: find the exact-source QA requirement, then the original-checkout comparison and expiry check. Explain why a stale proposal must be refreshed rather than forced into the checkout.'),
          'Accepting a handoff does not integrate code. Apply is an explicit state-changing operator action; never bypass the baseline or evidence checks. This documentation task does not review or apply any live proposal.', [30,32,33,34])
    guide(36, 'Company Dash history backups and settings',
          'Locate persistent history, usage controls, backup verification and deliberate restoration.',
          ['http://127.0.0.1:8000/#activity', 'http://127.0.0.1:8000/#settings'], CD+'public/app.js', CD+'server/maintenance.mjs', CD+'server/usage.mjs',
          ['SQLite history and activity', 'Configuration diagnostics', 'Provider token usage', 'Optional usage thresholds', 'Checksummed backups', 'Restore to a new directory', 'Opt-in workspace retention'],
          ['Activity displays stored events; settings reads safe configuration and usage summaries from /api/state.',
           'Budget calculations combine provider usage with explicitly configured rates when available.',
           'Create backup requests POST /api/maintenance/backup after active and queued work has stopped.',
           'The server copies the database, reports and relevant workspaces and verifies a checksummed manifest.',
           'The restore command checks the backup and writes to a new data directory; retention previews precede deliberate cleanup.'],
          'data/ contains the SQLite database, reports and isolated workspaces and stays outside Git and the source library. config.local.json contains workstation settings; config.example.json explains the keys without revealing private values. Token usage is provider-reported. Dollar estimates need explicit rates; subscription billing is not inferred. Zero-valued thresholds and retention mean disabled defaults. Backups omit regenerable dependencies and build output. server/restore.mjs calls restoreBackup from maintenance.mjs and expects a backup directory and a new destination.',
          (CD+'server/maintenance.mjs', 'export async function backupData', None, 'Read-only exercise: find how backupData creates its manifest and how restoreBackup verifies each file. Then find retentionPlan and explain why previewing it does not delete history.'),
          'Usage thresholds act at provider turn boundaries and cannot guarantee an exact in-flight spending cap. A backup is not a successful restore test. Do not run cleanup or restoration against existing history while learning; the documentation task performs neither action.', [31,33,35])

OWNERS = [
    (CD+'public/', [31,32,33,34,35,36]),
    (CD+'server/app.mjs', [31,32,33,34,35,36]),
    (CD+'server/config.mjs', [31,36]),
    (CD+'server/repository.mjs', [32,35]),
    (CD+'server/runner.mjs', [33,34]),
    (CD+'server/catalog.mjs', [33,34]),
    (CD+'server/store.mjs', [33,36]),
    (CD+'server/proposals.mjs', [35]),
    (CD+'server/maintenance.mjs', [36]),
    (CD+'server/restore.mjs', [36]),
    (CD+'server/usage.mjs', [36]),
    (CD, [31,36]),
]
